result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/vm.py", "content": """"A tiny dict-coded stack VM (correct, but without function calls).

Code is a list of instruction dicts. Opcodes:

    PUSH v     push constant v
    ADD        pop b, pop a, push a + b
    MUL        pop b, pop a, push a * b
    LOAD n     push locals[n]
    STORE n    pop into locals[n]
    JMP a      jump to address a
    JZ a       pop; jump to a if the value is falsy
    RET_MAIN   halt, returning the top of the stack

Locals live in a flat list of 16 slots. There is a single operand stack
and no call frames.
"""


class VmError(Exception):
    """Raised for any runtime fault in the VM."""


class VM:
    NUM_LOCALS = 16

    def __init__(self, code):
        self.code = code
        self.pc = 0
        self.stack = []                      # the one and only operand stack
        self.locals = [None] * self.NUM_LOCALS

    # -- helpers -----------------------------------------------------
    def pop(self):
        if not self.stack:
            raise VmError('stack underflow')
        return self.stack.pop()

    def _binary(self, fn):
        b = self.pop()
        a = self.pop()
        self.stack.append(fn(a, b))

    # -- execution ---------------------------------------------------
    def step(self):
        """Execute one instruction; return True when halted."""
        if not (0 <= self.pc < len(self.code)):
            raise VmError('pc out of range: %r' % (self.pc,))
        ins = self.code[self.pc]
        handler = self.HANDLERS.get(ins.get('op'))
        if handler is None:
            raise VmError('unknown opcode: %r' % (ins.get('op'),))
        return handler(self, ins)

    def run(self):
        while not self.step():
            pass
        return self.stack[-1]

    # -- opcode implementations ---------------------------------------
    def op_push(self, ins):
        self.stack.append(ins['v'])
        self.pc += 1

    def op_add(self, ins):
        self._binary(lambda a, b: a + b)
        self.pc += 1

    def op_mul(self, ins):
        self._binary(lambda a, b: a * b)
        self.pc += 1

    def _slot(self, ins):
        n = ins['n']
        if not (0 <= n < self.NUM_LOCALS):
            raise VmError('bad local slot: %r' % (n,))
        return n

    def op_load(self, ins):
        self.stack.append(self.locals[self._slot(ins)])
        self.pc += 1

    def op_store(self, ins):
        self.locals[self._slot(ins)] = self.pop()
        self.pc += 1

    def op_jmp(self, ins):
        self.pc = ins['a']

    def op_jz(self, ins):
        self.pc = ins['a'] if not self.pop() else self.pc + 1

    def op_ret_main(self, ins):
        if not self.stack:
            raise VmError('stack underflow')
        return True                          # halt; run() returns stack top

    HANDLERS = {
        'PUSH': op_push,
        'ADD': op_add,
        'MUL': op_mul,
        'LOAD': op_load,
        'STORE': op_store,
        'JMP': op_jmp,
        'JZ': op_jz,
        'RET_MAIN': op_ret_main,
    }
"})
